package nz.tate.bankstanding;

import java.awt.image.BufferedImage;
import static org.junit.Assert.assertEquals;
import org.junit.Test;

public class HitsplatOverlayTest
{
	@Test
	public void maxHitSplatGetsABorderAroundItsShape()
	{
		BufferedImage splat = new BufferedImage(2, 2, BufferedImage.TYPE_INT_ARGB);
		splat.setRGB(0, 0, 0xFF640000);
		splat.setRGB(1, 0, 0xFF640000);

		BufferedImage out = HitsplatOverlay.bordered(splat);

		assertEquals(4, out.getWidth());
		assertEquals(0xFF780000, out.getRGB(1, 1));
		assertEquals(0xFFF0C450, out.getRGB(1, 0));
		assertEquals(0xFFF0C450, out.getRGB(1, 2));
		assertEquals(0, out.getRGB(0, 0));
		assertEquals(0, out.getRGB(1, 3));
	}
}

package nz.tate.bankstanding;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class PoisonTest
{
	@Test
	public void poisonedAndToxicItems()
	{
		assertTrue(BankStandingPlugin.isPoisonous("Dragon dagger(p++)"));
		assertTrue(BankStandingPlugin.isPoisonous("Abyssal tentacle (kp)"));
		assertTrue(BankStandingPlugin.isPoisonous("Toxic blowpipe"));
		assertTrue(BankStandingPlugin.isPoisonous("Serpentine helm"));
		assertFalse(BankStandingPlugin.isPoisonous("Dragon dagger"));
		assertFalse(BankStandingPlugin.isPoisonous(null));
