package nz.tate.bankstanding.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class RecordsTest
{
	private static final long START = 1_700_000_000_000L;
	private static final long TICK = 600;

	private final Progress progress = new Progress();
	private final Session session = new Session();

	/** Stands for {@code ticks}, earning {@code xpPerRoll} each roll, like the plugin does. */
	private long stand(long now, int ticks, int xpPerRoll)
	{
		for (int i = 1; i <= ticks; i++)
		{
			now += TICK;
			session.ticks++;
			DailyStreak.standingTick(progress, java.time.LocalDate.of(2026, 1, 1));
			progress.records.standingTick(progress, session, now);
			if (i % XpRoller.ROLL_INTERVAL_TICKS == 0)
			{
				int before = progress.xp;
				progress.xp = Experience.addXp(progress.xp, xpPerRoll);
				session.xp += progress.xp - before;
				progress.records.gainedXp(before, progress.xp, now);
			}
		}
		return now;
	}

	@Test
	public void startsFromAnExistingSave()
	{
		progress.xp = 5000;
		progress.bank("varrock-west", 3185, 3436).ticks = 1234;
		progress.records.begin(progress, START);
		assertEquals(START, progress.records.firstSeen);
		assertEquals(1234, progress.records.totalTicks);
		assertEquals("start", progress.records.milestones.get(0).kind);

		progress.records.begin(progress, START + 999);
		assertEquals(START, progress.records.firstSeen);
	}

	@Test
	public void honestPlayHasAConsistentHistory()
	{
		progress.records.begin(progress, START);
		long now = stand(START, 20_000, 10);
		assertTrue(progress.records.check(progress, now).isEmpty());
		assertNotNull(progress.records.find("level", 10));
		assertNotNull(progress.records.findStand(60));
		assertNotNull(progress.records.findStand(180));
		assertEquals(20_000, progress.records.longestStandTicks);
		assertTrue(progress.records.bestXpPerHour > 0);
		assertEquals(20_000, progress.records.bestDayTicks);
	}

	@Test
	public void aStandEndingResetsTheCurrentStand()
	{
		progress.records.begin(progress, START);
		long now = stand(START, 100, 1);
		progress.records.standEnded();
		stand(now, 50, 1);
		assertEquals(100, progress.records.longestStandTicks);
		assertEquals(150, progress.records.totalTicks);
	}

	@Test
	public void theLongestStandFitsBeforeTheSixHourLogout()
	{
		progress.records.begin(progress, START);
		stand(START, 35_000, 1);
		assertNotNull(progress.records.findStand(350));
		assertTrue(350 * Records.TICKS_PER_MINUTE < 6 * Records.TICKS_PER_HOUR - 50);
	}

	@Test
	public void olderSavesKeepTheirHourMilestones()
	{
		progress.records.begin(progress, START);
		progress.records.milestones.add(new Records.Milestone("stand", 1, START, 6000, 0));
		stand(START, 6000, 1);
		assertNotNull(progress.records.findStand(60));
		int stands = 0;
		for (Records.Milestone milestone : progress.records.milestones)
		{
			stands += milestone.kind.equals("stand") ? 1 : 0;
		}
		assertEquals(1, stands);
	}

	@Test
	public void editedXpIsCaught()
	{
		progress.records.begin(progress, START);
		long now = stand(START, 600, 5);
		progress.xp = 50_000_000;
		assertFalse(progress.records.check(progress, now).isEmpty());
	}

	@Test
	public void tooMuchStandingTimeIsCaught()
	{
		progress.records.begin(progress, START);
		long now = stand(START, 6000, 5);
		Records.Milestone hour = progress.records.findStand(60);
		hour.at = START + 60_000;
		assertFalse(progress.records.check(progress, now).isEmpty());
	}

	@Test
	public void developerChangesAreFlagged()
	{
		progress.records.begin(progress, START);
		progress.records.edited = true;
		assertFalse(progress.records.check(progress, START).isEmpty());
	}

	@Test
	public void theBestRateNeedsHalfAnHour()
	{
		progress.records.begin(progress, START);
		stand(START, 2000, 50);
		assertEquals(0, progress.records.bestXpPerHour);
	}
}

package nz.tate.bankstanding.core;

import com.google.gson.Gson;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/** A save written by 1.0 must load into the current code with nothing lost. */
public class SaveCompatibilityTest
{
	private static final String SAVE_1_0 = "{\"xp\":13034431,"
		+ "\"banks\":{\"ge\":{\"ticks\":60000,\"xp\":13000000,\"x\":3164,\"y\":3487}},"
		+ "\"streakDate\":\"2026-10-14\",\"streakDays\":3,\"todayDate\":\"2026-10-14\",\"todayTicks\":1200,"
		+ "\"keywordPaid\":{\"abc\":1},\"keywordDate\":\"2026-10-14\",\"keywordCount\":1,"
		+ "\"records\":{\"firstSeen\":1,\"totalTicks\":60000,\"longestStandTicks\":7000,\"milestones\":[]},"
		+ "\"collection\":{\"lost-bank-pin\":{\"count\":2,\"firstAt\":5,\"firstRolls\":40}},\"rolls\":99999}";

	@Test
	public void oneZeroSavesLoadWithEverythingKept()
	{
		Progress p = new Gson().fromJson(SAVE_1_0, Progress.class);
		assertEquals(13034431, p.xp);
		assertEquals(60000, p.banks.get("ge").ticks);
		assertEquals(3, p.streakDays);
		assertEquals(99999, p.rolls);
		assertEquals(2, p.collection.get("lost-bank-pin").count);
		assertEquals(7000, p.records.longestStandTicks);
		assertTrue(p.keywordPaid.containsKey("abc"));

		assertNotNull(p.moments);
		assertNotNull(p.daysStood);
		assertEquals(0, p.lastSitRoll);
	}

	@Test
	public void savesSurviveARoundTrip()
	{
		Gson gson = new Gson();
		Progress p = gson.fromJson(SAVE_1_0, Progress.class);
		p.moments.put("odd:midnight", 7L);
		p.daysStood.add("2026-10-15");
		Progress again = gson.fromJson(gson.toJson(p), Progress.class);
		assertEquals(13034431, again.xp);
		assertEquals(Long.valueOf(7), again.moments.get("odd:midnight"));
		assertTrue(again.daysStood.contains("2026-10-15"));
	}
}

